import fs from 'node:fs';
import cp from 'node:child_process';
import { parseSync } from 'oxc-parser';

const introduced = cp.execFileSync('git', ['diff', '--name-only', '--diff-filter=A', '23ee5a756a76b72c0dce0c9f44f82c09c60e443b', 'HEAD', '--', 'src'], { encoding: 'utf8' }).trim().split('\n');
const untracked = cp.execFileSync('git', ['ls-files', '--others', '--exclude-standard', 'src'], { encoding: 'utf8' }).trim().split('\n');
const paths = [...new Set([...introduced, ...untracked])].filter((p) => p.endsWith('.ts')).sort();
const functions = new Set(['FunctionDeclaration', 'FunctionExpression', 'ArrowFunctionExpression']);
const controls = new Set(['IfStatement', 'ForStatement', 'ForInStatement', 'ForOfStatement', 'WhileStatement', 'DoWhileStatement', 'SwitchStatement', 'TryStatement']);
const decisions = new Set([...controls].filter((s) => !['TryStatement', 'SwitchStatement'].includes(s)).concat(['CatchClause', 'ConditionalExpression', 'SwitchCase']));
const violations = [];
const children = (node) => Object.values(node).flatMap((value) => Array.isArray(value) ? value : [value]).filter((value) => value && typeof value === 'object' && typeof value.type === 'string');
const results = paths.map((path) => {
  const code = fs.readFileSync(path, 'utf8');
  const parsed = parseSync(path, code);
  if (parsed.errors.length) throw new Error(JSON.stringify(parsed.errors));
  const found = [];
  const line = (offset) => code.slice(0, offset).split('\n').length;
  const walk = (node) => {
    if (functions.has(node.type) && node.body) {
      let complexity = 1;
      let nesting = 0;
      const bodyWalk = (child, depth) => {
        if (functions.has(child.type)) return;
        if (decisions.has(child.type) && (child.type !== 'SwitchCase' || child.test)) complexity++;
        if (child.type === 'LogicalExpression') complexity++;
        const next = depth + (controls.has(child.type) ? 1 : 0);
        nesting = Math.max(nesting, next);
        children(child).forEach((part) => bodyWalk(part, next));
      };
      bodyWalk(node.body, 0);
      const detail = { start: line(node.start), lines: line(node.end) - line(node.start) + 1, complexity, nesting };
      found.push(detail);
      if (detail.lines > 50 || complexity > 10 || nesting > 3) violations.push({ path, ...detail });
    }
    children(node).forEach(walk);
  };
  walk(parsed.program);
  const lines = code.trimEnd().split(/\r?\n/).length;
  if (lines > 800) violations.push({ path, lines });
  return { path, lines, functions: found.length, maxFunctionLines: Math.max(0, ...found.map((f) => f.lines)), maxComplexity: Math.max(0, ...found.map((f) => f.complexity)), maxNesting: Math.max(0, ...found.map((f) => f.nesting)) };
});
fs.writeFileSync('.codex/p3-element-quality.json', JSON.stringify({ parser: 'Installed oxc-parser', scope: 'All new TypeScript files, including callbacks; nested function bodies measured separately', results, violations }, null, 2) + '\n');
process.stdout.write(JSON.stringify({ files: results.length, violations }) + '\n');
process.exitCode = violations.length ? 1 : 0;
